      "rank": 1,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and geometric phase exposed directly observable consequences of quantum phase and reshaped quantum theory and experiment.",
        "attribution": "Aharonov is central to the nonlocal phase effect, while Berry established the broadly applicable adiabatic geometric phase.",
        "maturity": "Both effects have been repeatedly and precisely demonstrated across many quantum platforms over decades.",
        "uncertainties": [
          "The two discoveries are related conceptually but arose separately, so their fit as one unified prize requires careful framing."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B033",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks made an extraordinary advance in precision measurement while controlling quantum systematic effects at an unprecedented level.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept and Ye made defining experimental and metrological advances.",
        "maturity": "Independent laboratories now operate lattice clocks with remarkable reproducibility and broad scientific utility.",
        "uncertainties": [
          "The eventual redefinition and deployment consequences remain matters for metrology institutions, though the physics is mature."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided one of the cleanest realizations of controllable many-body quantum dynamics and quantum information processing.",
        "attribution": "Cirac and Zoller supplied seminal architectures and protocols; Blatt led landmark experimental implementations.",
        "maturity": "The platform has delivered high-fidelity control, entanglement, algorithms, and cross-laboratory replication over many years.",
        "uncertainties": [
          "Quantum computing as a general application is unfinished, but the underlying experimental physics is firmly established."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Carlton M. Caves",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed light converted a fundamental quantum-optical resource into a demonstrated means of surpassing classical interferometric sensitivity.",
        "attribution": "Caves gave the decisive quantum-noise analysis, and Schnabel led influential experimental development and deployment.",
        "maturity": "The method is experimentally robust and used in precision interferometry, including gravitational-wave observatories.",
        "uncertainties": [
          "The allocation of experimental credit across the wider squeezed-light and interferometry communities needs close examination."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B059",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics made light-matter interaction in electrical circuits a controllable quantum-optical regime and transformed superconducting-qubit science.",
        "attribution": "Blais supplied a foundational theoretical formulation; Wallraff and Schoelkopf made decisive early experimental demonstrations.",
        "maturity": "The physics has been reproduced extensively and is now a core architecture for quantum measurement and processing.",
        "uncertainties": [
          "Its proximity to recently recognized superconducting-circuit advances may call for unusually sharp delineation of the discovery."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B027",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "John D. Teufel",
        "Markus Aspelmeyer"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum control of mechanical motion made macroscopic vibrational systems accessible to quantum preparation, measurement, and coherent coupling.",
        "attribution": "Cleland and Teufel achieved defining circuit-based quantum experiments, while Aspelmeyer developed and advanced the broader optomechanics field.",
        "maturity": "Ground-state cooling, quantum-limited measurement, and coherent control have been convincingly reproduced.",
        "uncertainties": [
          "A prize definition spanning circuit and optical implementations may leave important contributors outside a three-person award."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution and teleportation established operational uses of entanglement and quantum information that changed how quantum theory is understood.",
        "attribution": "Bennett and Brassard introduced foundational cryptographic protocols, and Ekert established the entanglement-based approach.",
        "maturity": "The concepts have received extensive experimental verification and form a durable basis for quantum communication.",
        "uncertainties": [
          "Teleportation and cryptography have broad, overlapping intellectual lineages that complicate a compact attribution."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory supplied a powerful nonperturbative framework for correlated electrons and made contact with real materials.",
        "attribution": "Georges, Kotliar, and Vollhardt were central architects of the modern theory and its broad adoption.",
        "maturity": "The method is a mature standard tool with extensive successful applications and experimental connections.",
        "uncertainties": [
          "Its status as a methodological framework rather than a single discovery makes the most appropriate prize citation less clear."
        ]
      }
    }
  ]
